// Monta a pagina de prospeccao. Renderizado aqui no n8n porque o gateway
// do Supabase forca text/plain e nao deixa servir HTML.
const d = $input.first().json;

if (!d || !d.empresa) {
  return [{ json: { achou: false, html: paginaVazia() } }];
}

function esc(v) {
  return String(v == null ? '' : v)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;')
    .split('"').join('&quot;');
}
function nota(n) { return n == null ? '' : String(n).replace('.', ','); }

function paginaVazia() {
  return '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">'
    + '<meta name="robots" content="noindex, nofollow"><title>Pagina nao encontrada</title>'
    + '<style>body{margin:0;background:#0A0A0A;color:#FAFAF7;font-family:system-ui,Arial,sans-serif;'
    + 'display:flex;min-height:100vh;align-items:center;justify-content:center;padding:24px;text-align:center}'
    + 'a{color:#D9ED4F}</style></head><body><div>'
    + '<p style="font-size:26px;font-weight:700;margin:0 0 12px">sjdata<span style="color:#D9ED4F">.</span></p>'
    + '<p style="color:#A3A3A0;margin:0 0 20px">Esta p&aacute;gina n&atilde;o existe ou saiu do ar.</p>'
    + '<p style="margin:0"><a href="https://sjdata.com.br/">Ir para o site da SJDATA</a></p>'
    + '</div></body></html>';
}

const CDN = 'https://cdn.jsdelivr.net/gh/sjdata-sistemas/sjdata-site@909951f6448a29fb6103b2461f053ac5624250cd/publicado/img';
const ZAP = '5511976695896';
const ZAP_HUMANO = '(11) 97669-5896';

const curto = esc(d.nome_curto || d.empresa);
const peca = esc(d.peca);
const pecaNome = peca === 'sacada' ? 'envidraçamento de sacada' : peca;
const slug = esc(d.slug || '');
const url = 'https://sjdata.com.br/p/' + slug;

let chips = '';
if (d.nota) chips += '<div class="prova"><b>' + nota(d.nota) + '</b> no Google</div>';
if (d.avaliacoes) chips += '<div class="prova"><b>' + esc(d.avaliacoes) + '</b> avaliações</div>';
if (d.bairro || d.cidade) {
  chips += '<div class="prova">' + esc(d.bairro || '')
    + (d.bairro && d.cidade ? ', ' : '') + '<b>' + esc(d.cidade || '') + '</b></div>';
}

const metaOs = esc(d.endereco || '')
  + (d.bairro ? ' · ' + esc(d.bairro) : '')
  + (d.cidade ? ' · ' + esc(d.cidade) : '');

